header('Content-Type: application/xml; charset=utf-8');header('Cache-Control: public, max-age=300');$config=require __DIR__.'/site-runtime.php';$routes=['/','/conteudos','/guias','/noticias','/cases','/newsletter','/community','/ferramentas','/building','/produtos/growth-os','/sobre','/contato','/privacidade','/termos','/cookies','/ferramentas/claro','/ferramentas/checklist-conteudo','/ferramentas/calculadora-conversao','/ferramentas/planner-editorial'];$ch=curl_init($config['url'].'/rest/v1/content_posts?select=slug,updated_at&status=eq.published&published_at=lte.'.rawurlencode(gmdate('c')));curl_setopt_array($ch,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_TIMEOUT=>6,CURLOPT_HTTPHEADER=>['apikey: '.$config['key']]]);$data=curl_exec($ch);$status=curl_getinfo($ch,CURLINFO_HTTP_CODE);curl_close($ch);if($status!==200){readfile(__DIR__.'/sitemap.xml');exit;}$posts=json_decode($data,true)?:[];echo '<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">';foreach($routes as $r)echo '<url><loc>https://legendadigital.com.br'.htmlspecialchars($r,ENT_XML1).'</loc></url>';foreach($posts as $p)echo '<url><loc>https://legendadigital.com.br/conteudos/'.htmlspecialchars($p['slug'],ENT_XML1).'</loc><lastmod>'.htmlspecialchars(substr($p['updated_at'],0,10),ENT_XML1).'</lastmod></url>';echo '</urlset>';
